def _decode_header(value: str | email.header.Header) -> tuple[bool, str]:
    """Decode an RFC 2047 header while enforcing the metadata UTF-8 rule."""
    decoded: list[str] = []
    try:
        chunks = email.header.decode_header(value)
    except (TypeError, ValueError):
        return False, str(value)

    for chunk, _encoding in chunks:
        if isinstance(chunk, bytes):
            try:
                decoded.append(chunk.decode("utf-8"))
            except UnicodeDecodeError:
                return False, str(value)
        else:
            decoded.append(chunk)
    return True, "".join(decoded)


def parse_email(data: bytes | str) -> tuple[RawMetadata, dict[str, list[str]]]:
    """Parse core metadata represented as an RFC822-style message."""
    if isinstance(data, bytes):
        parsed = email.parser.BytesParser(policy=email.policy.compat32).parsebytes(data)
    else:
        parsed = email.parser.Parser(policy=email.policy.compat32).parsestr(data)

    headers: dict[str, list[str]] = {}
    invalid_encoding: set[str] = set()
    for name, value in parsed.items():
        normalized_name = name.lower()
        valid, decoded = _decode_header(value)
        headers.setdefault(normalized_name, []).append(decoded)
        if not valid:
            invalid_encoding.add(normalized_name)

    raw: RawMetadata = {}
    unparsed: dict[str, list[str]] = {}

    for name, values in headers.items():
        raw_name = _EMAIL_TO_RAW_MAPPING.get(name)
        if raw_name is None or name in invalid_encoding:
            unparsed[name] = values
            continue

        if raw_name in _STRING_FIELDS:
            if len(values) != 1:
                unparsed[name] = values
            else:
                raw[raw_name] = values[0]  # type: ignore[literal-required]
        elif raw_name == "keywords":
            if len(values) != 1:
                unparsed[name] = values
            else:
                raw["keywords"] = [item.strip() for item in values[0].split(",")]
        elif raw_name in _LIST_FIELDS:
            if raw_name == "import_names" and values == [""]:
                raw["import_names"] = []
            else:
                raw[raw_name] = values  # type: ignore[literal-required]
        elif raw_name in _DICT_FIELDS:
            project_urls: dict[str, str] = {}
            valid = True
            for value in values:
                parts = value.split(",", 1)
                if len(parts) != 2:
                    valid = False
                    break
                label, url = (part.strip() for part in parts)
                if label in project_urls:
                    valid = False
                    break
                project_urls[label] = url
            if valid:
                raw["project_urls"] = project_urls
            else:
                unparsed[name] = values

    payload: str | bytes | None
    if isinstance(data, bytes):
        payload_bytes = parsed.get_payload(decode=True)
        if payload_bytes:
            try:
                payload = payload_bytes.decode("utf-8")
            except UnicodeDecodeError:
                payload = payload_bytes
        else:
            payload = None
    else:
        parsed_payload = parsed.get_payload()
        payload = (
            parsed_payload
            if isinstance(parsed_payload, str) and parsed_payload
            else None
        )

    if payload is not None:
        if "description" in unparsed:
            unparsed["description"].append(payload)  # type: ignore[arg-type]
        elif "description" in raw:
            description = cast(str, raw.pop("description"))
            unparsed["description"] = [description, payload]  # type: ignore[list-item]
        elif isinstance(payload, bytes):
            unparsed["description"] = [payload]  # type: ignore[list-item]
        else:
            raw["description"] = payload

    return raw, unparsed


































































