                _VALID_METADATA_VERSIONS.index(self.added)
            ):
                raise self._invalid_metadata(
                    f"{{field}} is not allowed in metadata version {metadata_version!r}"
                )

        processor = getattr(self, f"_process_{self.name}", None)
        if processor is None:
            return cast(T, value)
        return cast(T, processor(value))

