        return InvalidMetadata(self.raw_name, message.format(field=self.raw_name))

    def _process_metadata_version(self, value: str) -> _MetadataVersion:
        if value not in _VALID_METADATA_VERSIONS:
            raise self._invalid_metadata(f"{value!r} is not a valid metadata version")
        return cast(_MetadataVersion, value)

    def _process_name(self, value: str) -> str:
        if not value:
            raise self._invalid_metadata("{field} is a required field")
        try:
            utils.canonicalize_name(value, validate=True)
        except utils.InvalidName as exc:
            raise self._invalid_metadata(f"{value!r} is invalid for {{field}}") from exc
        return value

    def _process_version(self, value: str) -> version_module.Version:
        if not value:
            raise self._invalid_metadata("{field} is a required field")
        try:
            return version_module.Version(value)
        except version_module.InvalidVersion as exc:
            raise self._invalid_metadata(f"{value!r} is invalid for {{field}}") from exc

    def _process_summary(self, value: str) -> str:
        if "\n" in value:
            raise self._invalid_metadata("{field} must be a single line")
        return value

    def _process_description_content_type(self, value: str) -> str:
        message = email.message.Message()
        try:
            message["content-type"] = value
            content_type = message.get_content_type().lower()
            parameters = message.get_params()[1:] if message.get_params() else []
        except (IndexError, TypeError, ValueError) as exc:
            raise self._invalid_metadata(f"{value!r} is invalid for {{field}}") from exc

        allowed_types = {"text/plain", "text/x-rst", "text/markdown"}
        declared_type = value.split(";", 1)[0].strip().lower()
        if content_type not in allowed_types or declared_type != content_type:
            raise self._invalid_metadata(
                f"{content_type!r} is not a valid {{field}}"
            )

        allowed_parameters = {"charset"}
        if content_type == "text/markdown":
            allowed_parameters.add("variant")

        for parameter, parameter_value in parameters:
            parameter = parameter.lower()
            if parameter not in allowed_parameters:
                raise self._invalid_metadata(
                    f"{parameter!r} is an invalid parameter for {{field}}"
                )
            if parameter == "charset" and str(parameter_value).lower() != "utf-8":
                raise self._invalid_metadata("charset for {field} must be UTF-8")
            if parameter == "variant" and str(parameter_value).lower() not in {
                "gfm",
                "commonmark",
            }:
                raise self._invalid_metadata(
                    "variant for {field} must be GFM or CommonMark"
                )
        return value

    def _process_dynamic(self, value: list[str]) -> list[str]:
        dynamic = [field.lower() for field in value]
        for field in dynamic:
            if field in {"name", "version", "metadata-version"}:
                raise self._invalid_metadata(
                    f"{field!r} is not allowed as a dynamic field"
                )
            if field not in _EMAIL_TO_RAW_MAPPING:
                raise self._invalid_metadata(
                    f"{field!r} is not a valid dynamic field"
                )
        return dynamic

    def _process_license_expression(
        self, value: str
    ) -> NormalizedLicenseExpression:
        try:
            return licenses.canonicalize_license_expression(value)
        except licenses.InvalidLicenseExpression as exc:
            raise self._invalid_metadata(f"{value!r} is invalid for {{field}}") from exc

    def _process_license_files(self, value: list[str]) -> list[str]:
        for license_file in value:
            posix_path = pathlib.PurePosixPath(license_file)
            windows_path = pathlib.PureWindowsPath(license_file)
            if ".." in posix_path.parts or ".." in windows_path.parts:
                raise self._invalid_metadata(
                    f"{license_file!r} contains a parent directory indicator"
                )
            if "*" in license_file:
                raise self._invalid_metadata(
                    f"{license_file!r} contains an unresolved glob pattern"
                )
            if (
                posix_path.is_absolute()
                or windows_path.is_absolute()
                or bool(windows_path.drive)
            ):
                raise self._invalid_metadata(f"{license_file!r} is an absolute path")
            if "\\" in license_file:
                raise self._invalid_metadata(
                    f"{license_file!r} uses an invalid path separator"
                )
        return value

    def _process_provides_extra(
        self, value: list[str]
    ) -> list[utils.NormalizedName]:
        normalized: list[utils.NormalizedName] = []
        for extra in value:
            try:
                normalized.append(utils.canonicalize_name(extra, validate=True))
            except utils.InvalidName as exc:
                raise self._invalid_metadata(
                    f"{extra!r} is invalid for {{field}}"
                ) from exc
        return normalized

    def _process_requires_dist(
        self, value: list[str]
    ) -> list[requirements.Requirement]:
        parsed: list[requirements.Requirement] = []
        for requirement in value:
            try:
                parsed.append(requirements.Requirement(requirement))
            except requirements.InvalidRequirement as exc:
                raise self._invalid_metadata(
                    f"{requirement!r} is invalid for {{field}}"
                ) from exc
        return parsed

    def _process_requires_python(self, value: str) -> specifiers.SpecifierSet:
        try:
            return specifiers.SpecifierSet(value)
        except specifiers.InvalidSpecifier as exc:
            raise self._invalid_metadata(f"{value!r} is invalid for {{field}}") from exc




























































































































































































    def _process_import_names(self, value: list[str]) -> list[str]:
        for import_name in value:
            name, semicolon, private = import_name.partition(";")
            name = name.rstrip()
            for identifier in name.split("."):
                if not identifier.isidentifier():
                    raise self._invalid_metadata(
                        f"{name!r} is invalid for {{field}}; "
                        f"{identifier!r} is not a valid identifier"
                    )
                elif keyword.iskeyword(identifier):
                    raise self._invalid_metadata(
                        f"{name!r} is invalid for {{field}}; "
                        f"{identifier!r} is a keyword"
                    )
            if semicolon and private.lstrip() != "private":
                raise self._invalid_metadata(
                    f"{import_name!r} is invalid for {{field}}; "
                    "the only valid option is 'private'"
                )
        return value

    _process_import_namespaces = _process_import_names


class Metadata:
    """Representation of distribution metadata.

    Compared to :class:`RawMetadata`, this class provides objects representing
    metadata fields instead of only using built-in types. Any invalid metadata
    will cause :exc:`InvalidMetadata` to be raised (with a
    :py:attr:`~BaseException.__cause__` attribute as appropriate).
    """

    _raw: RawMetadata

    @classmethod
    def from_raw(cls, data: RawMetadata, *, validate: bool = True) -> Metadata:
        instance = cls()
        instance._raw = cast(RawMetadata, dict(data))

        if validate:
            exceptions: list[Exception] = []
            metadata_version_valid = True
            try:
                instance.metadata_version
            except InvalidMetadata as exc:
                exceptions.append(exc)
                metadata_version_valid = False

            failed_fields: set[str] = set()
            for name, descriptor in cls.__dict__.items():
                if not isinstance(descriptor, _Validator) or name == "metadata_version":
                    continue
                if name not in instance._raw and name not in _REQUIRED_ATTRS:
                    continue
                try:
                    if metadata_version_valid or name not in instance._raw:
                        getattr(instance, name)
                    else:
                        value = instance._raw[name]  # type: ignore[literal-required]
                        processor = getattr(descriptor, f"_process_{name}", None)
                        if processor is not None:
                            processor(value)
                except InvalidMetadata as exc:
                    failed_fields.add(name)
                    exceptions.append(exc)

            if not ({"import_names", "import_namespaces"} & failed_fields):
                import_names = {
                    item.partition(";")[0].rstrip()
                    for item in instance._raw.get("import_names", [])
                }
                import_namespaces = {
                    item.partition(";")[0].rstrip()
                    for item in instance._raw.get("import_namespaces", [])
                }
                overlap = import_names & import_namespaces
                if overlap:
                    exceptions.append(
                        InvalidMetadata(
                            "import-name",
                            "import names and namespaces must not overlap: "
                            + ", ".join(sorted(overlap)),
                        )
                    )

            if exceptions:
                raise ExceptionGroup("invalid metadata", exceptions)

        return instance

    @classmethod
    def from_email(cls, data: bytes | str, *, validate: bool = True) -> Metadata:
        raw, unparsed = parse_email(data)
        if validate and unparsed:
            exceptions = [
                InvalidMetadata(name, f"{name!r} has invalid data")
                for name in unparsed
            ]
            raise ExceptionGroup("unparsed", exceptions)
        return cls.from_raw(raw, validate=validate)

    def as_rfc822(self) -> RFC822Message:
        message = RFC822Message()
        for email_name, raw_name in _EMAIL_TO_RAW_MAPPING.items():
            value = getattr(self, raw_name)
            if value is None or raw_name == "description":
                continue

            if raw_name == "keywords":
                message[email_name] = ",".join(value)
            elif raw_name == "project_urls":
                for label, url in value.items():
                    message[email_name] = f"{label}, {url}"
            elif isinstance(value, list):
                if raw_name == "import_names" and not value:
                    message[email_name] = ""
                else:
                    for item in value:
                        message[email_name] = str(item)
            else:
                message[email_name] = str(value)

        description = self.description
        if description is not None:
            message.set_payload(description)
        return message

